function units(dir){const angle=dir*Math.PI/4,dx=-Math.sin(angle),dy=Math.cos(angle)*.65;return Array.from({length:6},(_,i)=>({x:(2.5-i)*11*dx,y:(2.5-i)*11*dy,scale:i===0?.68:.6,leader:i===0})).sort((a,b)=>a.y-b.y)}
