function portrait(id,dir=0,animated=false){const f=frame(id,'Idle',dir,0);if(!f)return null;const b=f.m.bounds[f.row][0];if(!b)return null;if(!f.species.formation&&!animated)return{bounds:b,anchor:f.anchor};const boxes=(f.species.formation?units(dir):[{x:0,y:0,scale:1}]).flatMap(u=>{const part=u.leader&&f.species.formationLeader?frameFor(f.species.formationLeader,'Idle',dir):f,indices=animated?part.m.durations.map((_,i)=>i):[0];return indices.filter(i=>part.m.bounds[part.row][i]).map(i=>{const a=part.m.anchors[part.row][i],b=part.m.bounds[part.row][i];return[u.x+(b[0]-a[0])*u.scale,u.y+(b[1]-a[1])*u.scale,u.x+(b[2]-a[0])*u.scale,u.y+(b[3]-a[1])*u.scale]})});return{bounds:[Math.min(...boxes.map(v=>v[0])),Math.min(...boxes.map(v=>v[1])),Math.max(...boxes.map(v=>v[2])),Math.max(...boxes.map(v=>v[3]))],anchor:[0,0]}}
function extent(id){const species=SPRITES[id];if(species?.formation){const boxes=Array.from({length:8},(_,dir)=>portrait(id,dir,true)?.bounds).filter(Boolean);return Math.max(32,...boxes.map(b=>Math.max(b[2]-b[0],b[3]-b[1])))}const first=species?.animations.Idle.bounds?.[0]?.[0];if(Number(id)<=151||Number(id)===200)return first?Math.max(first[2]-first[0],first[3]-first[1]):32;const all=species?.animations.Idle.bounds?.flat().filter(Boolean)||[];return Math.max(1,...all.map(b=>Math.max(b[2]-b[0],b[3]-b[1])),first?0:32)}
